-- Re-running is safe: rows are matched by slug.
-- Adopt existing root categories of the same name.
UPDATE categories SET slug = 'computer-science' WHERE parent_id IS NULL AND lower(name) = lower('Computer Science') AND slug <> 'computer-science';
UPDATE categories SET slug = 'programming' WHERE parent_id IS NULL AND lower(name) = lower('Programming') AND slug <> 'programming';
UPDATE categories SET slug = 'architecture' WHERE parent_id IS NULL AND lower(name) = lower('Architecture') AND slug <> 'architecture';
