UPDATE categories SET slug = 'best-practices' WHERE parent_id IS NULL AND lower(name) = lower('Best Practices') AND slug <> 'best-practices';
UPDATE categories SET slug = 'devops' WHERE parent_id IS NULL AND lower(name) = lower('DevOps') AND slug <> 'devops';
UPDATE categories SET slug = 'cyber-security' WHERE parent_id IS NULL AND lower(name) = lower('Cyber Security') AND slug <> 'cyber-security';
UPDATE categories SET slug = 'ai-intelligent-systems' WHERE parent_id IS NULL AND lower(name) = lower('AI & Intelligent Systems') AND slug <> 'ai-intelligent-systems';
UPDATE categories SET slug = 'leadership-soft-skills' WHERE parent_id IS NULL AND lower(name) = lower('Leadership & Soft Skills') AND slug <> 'leadership-soft-skills';

